"""Service/work/business catalogue mapped to canonical Global CORE domain IDs."""
SERVICES=tuple({"service_id":x[0],"name":x[1],"domain_id":x[2],"description":x[3]} for x in [["msme_development","MSME Development","msme","Enterprise assessment, formalization readiness and growth support."],["sme_growth_advisory","SME Growth Advisory","sme","Strategy, productivity, operations and expansion advisory."],["startup_formation","Startup Formation Support","startups","Venture setup planning and founder readiness."],["solo_business_setup","Solo Business Setup","solo_preneurship","Independent business model and owner-operator workflows."],["solo_preneur_coaching","Solo-preneur Coaching","solo_preneur","Positioning, productivity and sustainable solo operations."],["business_men_networking","Business Men Networking","business_men","Peer communities and leadership development."],["business_women_networking","Business Women Networking","business_women","Peer communities and leadership development."],["women_led_business_advisory","Women-led Business Advisory","women_preneurship","Founder support, market access and business growth."],["women_entrepreneurship_programs","Women Entrepreneurship Programs","women_preneur","Education, mentoring and venture readiness."],["men_led_business_advisory","Men-led Business Advisory","men_preneurship","Founder support, business planning and growth."],["men_entrepreneurship_programs","Men Entrepreneurship Programs","men_preneur","Education, mentoring and venture readiness."],["entrepreneur_coaching","Entrepreneur Coaching and Mentoring","entrepreneurs","Founder coaching, mentoring and accountability."],["business_plan_strategy","Business Plan and Strategy","entrepreneurship","Business plans, feasibility and execution roadmaps."],["market_customer_research","Market and Customer Research","entrepreneurial_research","Market sizing, customer discovery and competitor research."],["business_research_analytics","Business Research and Analytics","business_research","Commercial research, benchmarking and decision support."],["innovation_consulting","Innovation Consulting","innovation","Innovation strategy, design and commercialization planning."],["business_creation_readiness","Business Creation Readiness","business_creation","Formation checklists and professional referral pathways."],["business_development_services","Business Development Services","business_development","Partnerships, channels and market entry."],["business_growth_consulting","Business Growth Consulting","business_growth","Revenue, acquisition, operations and scaling advisory."],["business_management_consulting","Business Management Consulting","business_management","Governance, finance, people and operating systems."],["business_model_design","Business Model Design Services","business_model_design","Value proposition, pricing and revenue architecture."],["startup_validation","Startup Validation Services","startup_validation","Customer interviews, MVP planning and validation research."],["incubation_acceleration","Incubation and Acceleration Support","incubation_acceleration","Incubator readiness, accelerator and venture studio support."],["funding_readiness","Funding and Investment Readiness","funding_investment_readiness","Funding strategy and investor due-diligence preparation."],["digital_business_services","Digital Business Services","digital_entrepreneurship","E-commerce, online operations and digital business development."],["ai_technology_business_services","AI and Technology Business Services","ai_technology_entrepreneurship","AI adoption, software venture and technology commercialization."],["rd_prototyping_services","R&D and Prototyping Services","research_development_rd","Research planning, prototyping, testing and product development."],["ip_commercialization","IP and Licensing Commercialization","intellectual_property_commercialization","IP mapping, licensing and technology transfer."],["social_rural_enterprise_support","Social and Rural Enterprise Support","social_rural_entrepreneurship","Impact venture design and inclusive market access."],["family_business_advisory","Family Business Advisory","family_business_succession","Governance, succession and family enterprise continuity."],["global_expansion_advisory","Export and Global Expansion Advisory","international_entrepreneurship","Export readiness and international market research."]])
def list_services(): return [dict(x) for x in SERVICES]
def get_service(key):
 k=key.strip().casefold(); return next((dict(x) for x in SERVICES if x["service_id"]==k),None)
def search_services(q):
 k=q.strip().casefold(); return [dict(x) for x in SERVICES if k and k in " ".join(x.values()).casefold()]
def validate_mappings(domain_ids):
 ids=[x["service_id"] for x in SERVICES]; missing=sorted({x["domain_id"] for x in SERVICES}-set(domain_ids))
 return {"valid":len(ids)==len(set(ids)) and not missing,"service_count":len(SERVICES),"unmapped_domain_ids":missing}
